questionvariables.text:
correct_answer:rand_selection([
[1, true, "Grouping method and non-grouping method"],
[2, true, "Grouping method and inspecting method"]
], 1);
incorrect_answers:rand_selection([
[3, false, "Grouping method and ascending method"],
[4, false, "Grouping method and descending method"],
[5, false, "Table method and midpoint method

"],
[6, false, "Table method and frequency method"],[7, false, "Ungrouped and grouped method


"]], 3);
ta: random_permutation(append(correct_answer,incorrect_answers));

ta_index: sort(makelist(x[1], x, ta));
ta_largest: last(ta_index);
